// Bun's APIs, from the bun module and the Bun global: spawn (web streams, exit codes, signals,
// piped stdin, a Blob as stdin), spawnSync, file (a Blob read from its file), write, sleep and
// semver. The same package under Bun prints the same.
import { spawn, file } from "bun";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { existsSync } from "node:fs";

export default async function run() {
  const p = spawn(["sh", "-c", "echo out; exit 3"]);
  console.log(typeof p.pid, p.exitCode, p.stdin, p.stdout instanceof ReadableStream, p.stderr);
  console.log(JSON.stringify(await new Response(p.stdout).text()), await p.exited, p.exitCode, p.signalCode);
  const q = Bun.spawn({ cmd: ["sleep", "5"], stdout: "pipe", stderr: "pipe" });
  q.kill();
  console.log(await q.exited, q.exitCode, q.signalCode, q.killed);
  const r = Bun.spawn(["cat"], { stdin: "pipe" });
  r.stdin.write("hello ");
  r.stdin.write(new TextEncoder().encode("world"));
  r.stdin.end();
  console.log(JSON.stringify(await new Response(r.stdout).text()), await r.exited);
  const s = Bun.spawnSync(["sh", "-c", "echo sync; exit 2"]);
  console.log(s.exitCode, s.success, JSON.stringify(s.stdout.toString()), s.stderr.length);
  const t = Bun.spawn(["cat"], { stdin: new Blob(["from blob"]) });
  console.log(await new Response(t.stdout).text());
  try {
    Bun.spawn(["/nonexistent/x"]);
  } catch (e) {
    console.log("spawn", e.code, e.message);
  }

  const path = join(tmpdir(), `bun-api-${process.pid}.txt`);
  console.log("write", await Bun.write(path, "hello file"));
  const f = file(path);
  console.log(f.size, f.type.split(";")[0], f.name === path, typeof f.lastModified, await f.exists(), await file(`${path}.nope`).exists(), file(`${path}.nope`).size);
  console.log(await f.text(), await f.slice(6).text(), f.slice(0, 5).size, f instanceof Blob, (await f.bytes()).length);
  console.log(await new Response(f.slice(1, 4)).text(), await new Blob([f]).text());
  try {
    await file(`${path}.nope`).text();
  } catch (e) {
    console.log("missing", e.code);
  }
  await f.delete();
  console.log("deleted", existsSync(path));

  const t0 = Date.now();
  await Bun.sleep(20);
  console.log("slept", Date.now() - t0 >= 19);
  const sv = Bun.semver;
  console.log(sv.satisfies("1.4.0", ">=1.4.0"), sv.satisfies("1.3.9", "^1.4"), sv.satisfies("1.4.2", "~1.4.0"), sv.satisfies("2.0.0-beta.1", ">=1.0.0"));
  console.log(sv.satisfies("1.2.3", "1.x || 2.x"), sv.satisfies("1.2.3", "1.0.0 - 1.2.2"), sv.satisfies("0.2.5", "^0.2.3"), sv.satisfies("0.3.0", "^0.2.3"));
  console.log(sv.order("1.2.3", "1.10.0"), sv.order("1.0.0", "1.0.0-rc.1"), sv.order("2.0.0", "2.0.0"));
  console.log(typeof Bun.version, Bun.which("sh") !== null, Bun.which("definitely-not-a-command"), Bun.env === process.env);
}
